// Set session storage to authenticate as a role quickly (avoids repeating OTP flow)
async function setAuth(page: Page, role: Exclude<Role, 'unauthenticated'>) {
  await page.goto(BASE_URL);
  await page.evaluate((user) => {
    sessionStorage.setItem('permit_user', JSON.stringify(user));
  }, MOCK_USERS[role]);
}

