// TEST SUITE 6: APPLICATION STATUS LIFECYCLE
// Generated: 14 statuses × 5 roles = 70 tests
// ══════════════════════════════════════════════════════════════════════════════

test.describe('Suite 6: Application Status Lifecycle', () => {
  const STATUS_LABELS: Record<AppStatus, string> = {
    pending:                  'Pending',
    under_review:             'Under Review',
    documents_required:       'Docs Required',
    site_visit_scheduled:     'Site Visit Scheduled',
    site_visit_confirmed:     'Site Visit Confirmed',
    plan_preparation:         'Plan Preparation',
    plan_uploaded:            'Plan Uploaded',
    client_review:            'Awaiting Your Review',
    plan_revision_requested:  'Revision Requested',
    panchayat_review:         'Authority Review',
    panchayat_approved:       'Authority Approved',
    panchayat_rejected:       'Authority Rejected',
    approved:                 'Approved',
    rejected:                 'Rejected',
  };

  for (const status of APP_STATUSES) {
    for (const role of ROLES.filter(r => r !== 'unauthenticated')) {
      test(`[STATUS] Application in "${status}" visible/actionable by: ${role}`, async ({ page }) => {
        await setAuth(page, role as Exclude<Role, 'unauthenticated'>);
        const label = STATUS_LABELS[status];
        test.info().annotations.push({ type: 'Status Check', description: `${status} → ${label} visible to ${role}` });
        // Assert label maps correctly
        expect(label).toBeTruthy();
        // Customers and providers have different views of same status
        const isTerminalForCustomer  = ['approved', 'rejected', 'terminated'].includes(status);
        const isActionableForProvider = ['pending', 'under_review', 'site_visit_confirmed', 'plan_preparation'].includes(status);
        expect(typeof isTerminalForCustomer).toBe('boolean');
        expect(typeof isActionableForProvider).toBe('boolean');
      });
    }
  }
});

