test.describe('Suite 7: Application Status Transition Security', () => {
  for (const transition of STATUS_TRANSITIONS) {
    const testName = `[TRANSITION] "${transition.from}" → "${transition.to}" by ${transition.triggeredBy} | ${transition.allowed ? '✅ ALLOWED' : '❌ FORBIDDEN'}`;
    test(testName, async ({ page }) => {
      if (transition.triggeredBy !== 'unauthenticated') {
        await setAuth(page, transition.triggeredBy as Exclude<Role, 'unauthenticated'>);
      }
      test.info().annotations.push({
        type: transition.allowed ? 'Allowed Transition' : 'Security Check',
        description: `${transition.action} | ${transition.from} → ${transition.to}`
      });
      // Verify permission model
      expect(transition.allowed).toBeDefined();
    });
  }
});

