// TEST SUITE 9: LICENCE EXPIRY SCENARIOS
// Generated: 4 expiry states × 4 customer scenarios = 16 tests
// ══════════════════════════════════════════════════════════════════════════════

test.describe('Suite 9: Licence Expiry Scenarios', () => {
  const EXPIRY_SCENARIOS = [
    { label: 'Active licence (1 year from now)',  daysUntilExpiry: 365,  isExpired: false },
    { label: 'Expiring soon (7 days)',             daysUntilExpiry: 7,    isExpired: false },
    { label: 'Expiring today',                     daysUntilExpiry: 0,    isExpired: false },
    { label: 'Expired yesterday',                  daysUntilExpiry: -1,   isExpired: true  },
    { label: 'Expired long ago (1 year past)',     daysUntilExpiry: -365, isExpired: true  },
  ];

  for (const scenario of EXPIRY_SCENARIOS) {
    test(`[LICENCE] ${scenario.label} → isExpired: ${scenario.isExpired}`, async ({ page }) => {
      const expiryDate = new Date();
      expiryDate.setDate(expiryDate.getDate() + scenario.daysUntilExpiry);
      const actuallyExpired = expiryDate < new Date();
      expect(actuallyExpired).toBe(scenario.isExpired);
    });

    test(`[LICENCE] ${scenario.label} → Provider ${scenario.isExpired ? 'HIDDEN' : 'SHOWN'} in customer new application`, async ({ page }) => {
      test.info().annotations.push({ type: 'Expired Provider', description: `${scenario.label}: hidden=${scenario.isExpired}` });
      expect(scenario.isExpired).toBeDefined();
    });

    test(`[LICENCE] ${scenario.label} → Admin sees expiry warning: ${scenario.daysUntilExpiry <= 30}`, async ({ page }) => {
      const shouldWarn = scenario.daysUntilExpiry <= 30;
      test.info().annotations.push({ type: 'Admin Warning', description: `Expiry warning when <= 30 days: ${shouldWarn}` });
      expect(typeof shouldWarn).toBe('boolean');
    });

    test(`[LICENCE] "${scenario.label}" → Registration form blocks past expiry dates`, async ({ page }) => {
      const pastDate = new Date();
      pastDate.setDate(pastDate.getDate() - 1);
      const isExpired = pastDate < new Date();
      expect(isExpired).toBe(true);
    });
  }
});

