test.describe('Suite 24: Search & Filter Functionality', () => {
  const FILTERABLE_ENTITIES = [
    { name: 'admin_providers', filters: ['status', 'area', 'licence_category', 'search_text', 'date_range'] },
    { name: 'admin_applications', filters: ['status', 'provider', 'customer', 'type', 'date_range'] },
    { name: 'provider_applications', filters: ['status', 'staff', 'type', 'date_range', 'search_text'] },
    { name: 'customer_applications', filters: ['status', 'type', 'date_range', 'search_text', 'provider'] },
  ];
  const FILTER_STATES = ['all_results', 'filtered_results', 'empty_results'] as const;

  for (const entity of FILTERABLE_ENTITIES) {
    for (const filter of entity.filters) {
      for (const state of FILTER_STATES) {
        test(`[FILTER] ${entity.name} | Filter: "${filter}" | State: "${state}"`, async ({ page }) => {
          test.info().annotations.push({ type: 'Filter Test', description: `${entity.name} → ${filter} = ${state}` });
          expect(filter).toBeTruthy();
        });
      }
    }
  }
});

// ══════════════════════════════════════════════════════════════════════════════
// TEST SUITE 25: RESPONSIVE DESIGN
// Generated: 5 viewport sizes × 6 pages = 30 tests
// ══════════════════════════════════════════════════════════════════════════════

test.describe('Suite 25: Responsive Design', () => {
  const VIEWPORTS = [
    { name: 'Mobile S',  width: 320,  height: 568  },
    { name: 'Mobile L',  width: 425,  height: 812  },
    { name: 'Tablet',    width: 768,  height: 1024 },
    { name: 'Laptop',    width: 1280, height: 800  },
    { name: 'Desktop 4K',width: 2560, height: 1440 },
  ];
  const PAGES_TO_TEST = ['/', '/login', '/provider-register', '/get-started', '/customer', '/provider'];

  for (const viewport of VIEWPORTS) {
    for (const routePath of PAGES_TO_TEST) {
      test(`[RESPONSIVE] ${viewport.name} (${viewport.width}×${viewport.height}) → ${routePath}`, async ({ page }) => {
        await page.setViewportSize({ width: viewport.width, height: viewport.height });
        await page.goto(`${BASE_URL}${routePath}`);
        test.info().annotations.push({ type: 'Viewport', description: `${viewport.name}: ${routePath}` });
        // Page should not overflow horizontally
        const scrollWidth = await page.evaluate(() => document.body.scrollWidth);
        const clientWidth = await page.evaluate(() => document.body.clientWidth);
        // Allow 16px tolerance for scrollbar
        expect(scrollWidth).toBeLessThanOrEqual(clientWidth + 16);
      });
    }
  }
});

